/* Feature: qr; classic script; vendors load before this file. */

function qrMods(t){const q=qrcode(0,"H");q.addData(t);q.make();return q}
function qrSvg(t){const q=qrMods(t),n=q.getModuleCount();let d="";for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(q.isDark(r,c))d+=`M${c} ${r}h1v1h-1z`;return `<svg viewBox="0 0 ${n} ${n}" shape-rendering="crispEdges"><path d="${d}" fill="#111"/></svg>`}
function recvSheet(){sheet(`<h2 style="text-align:center">استلام الأموال</h2><div class="qrbox" style="position:relative">${qrSvg(accountNo(me))}<img src="${LOGO_URL}" style="position:absolute;left:50%;top:50%;width:50px;height:50px;margin:-25px;border-radius:13px;border:4px solid #fff;background:#fff"></div><div class="lab">رقم الحساب (IBAN)</div><div class="big" style="font-size:16px">${accountNo(me)}</div>
<div class="rbtns"><button onclick="cpy()">${I("copy",22)}<span id="cl">نسخ IBAN</span></button><button onclick="shareCode()">${I("share-2",22)}مشاركة الكود</button><button onclick="saveImg()">${I("image-down",22)}حفظ الصورة</button></div>`)}
function qrBlob(){return new Promise(res=>{const q=qrMods(accountNo(me)),n=q.getModuleCount(),c=document.createElement("canvas");c.width=640;c.height=860;const x=c.getContext("2d");x.fillStyle="#fff";x.fillRect(0,0,640,860);x.fillStyle="#6a43f0";x.fillRect(0,0,640,110);x.fillStyle="#fff";x.font="bold 44px sans-serif";x.textAlign="center";x.fillText("الرفاه كاش",320,70);const z=Math.floor(480/n),off=(640-z*n)/2;x.fillStyle="#111";for(let r=0;r<n;r++)for(let k=0;k<n;k++)if(q.isDark(r,k))x.fillRect(off+k*z,160+r*z,z,z);x.fillStyle="#fff";x.fillRect(320-52,160+z*n/2-52,104,104);x.drawImage(LOGO_IMG,320-46,160+z*n/2-46,92,92);x.fillStyle="#555";x.font="24px sans-serif";x.fillText("رقم الحساب (IBAN)",320,730);x.fillStyle="#111";x.font="bold 30px monospace";x.fillText(accountNo(me),320,785);c.toBlob(res,"image/png")})}
async function saveImg(){const b=await qrBlob(),f=new File([b],"alrafah-cash-"+me.id+".png",{type:"image/png"});if(window.AlrafahAndroid&&await saveBlobFile(b,f.name,"image/png")){$("#cl").textContent="تم حفظ الشعار في مجلد التنزيلات ✓";return}try{if(navigator.canShare&&navigator.canShare({files:[f]})){await navigator.share({files:[f]});return}}catch(e){}try{const a=document.createElement("a");a.href=URL.createObjectURL(b);a.download=f.name;a.click();URL.revokeObjectURL(a.href);return}catch(e){}$("#cl").textContent="تعذّر حفظ الصورة هنا"}
async function shareCode(){const b=await qrBlob(),n='alrafah-cash-'+accountNo(me)+'.png';if(await shareBlobFile(b,n,'image/png'))return;const text='حوّل لي عبر الرفاه كاش\nIBAN: '+accountNo(me);try{if(navigator.share)await navigator.share({text});else await navigator.clipboard.writeText(text)}catch(e){}}
